'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notice=(text,error=false)=>{const el=$('#notice');el.textContent=text;el.classList.toggle('error',error)};
const learnerId=(()=>{let id=localStorage.getItem('franchiseos.academy.learner');if(!id){id=crypto.randomUUID().replaceAll('-','');localStorage.setItem('franchiseos.academy.learner',id)}return id})();
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Request failed (${response.status})`);return data}
function lessonCard(lesson,progress){return `<article class="lesson" data-lesson="${esc(lesson.id)}"><div class="lesson-meta"><span>${esc(lesson.courseTitle)}</span><span>·</span><span class="done">${progress?.completed?'Completed':''}</span></div><h3>${esc(lesson.title)}</h3><div class="language-tabs"><button data-language="en" aria-pressed="true">English</button><button data-language="te" aria-pressed="false">తెలుగు</button></div><p class="lesson-body" data-en="${esc(lesson.sourceText)}" data-te="${esc(lesson.teluguText)}">${esc(lesson.sourceText)}</p><div class="lesson-controls"><button class="button ${progress?.completed?'secondary':''}" data-complete="${esc(lesson.id)}">${progress?.completed?'Mark as not complete':'Mark lesson complete'}</button></div></article>`}
async function load(){try{const [{lessons},{progress}]=await Promise.all([api('/api/academy/lessons'),api('/api/academy/progress?learnerId='+encodeURIComponent(learnerId))]);const byLesson=new Map(progress.map(x=>[x.lessonId,x]));const groups=new Map();for(const lesson of lessons){if(!groups.has(lesson.courseId))groups.set(lesson.courseId,{title:lesson.courseTitle,description:lesson.courseDescription,lessons:[]});groups.get(lesson.courseId).lessons.push(lesson)}$('#courses').innerHTML=groups.size?[...groups.values()].map(course=>`<section class="course-card"><h2>${esc(course.title)}</h2><p class="course-desc">${esc(course.description)}</p>${course.lessons.map(lesson=>lessonCard(lesson,byLesson.get(lesson.id))).join('')}</section>`).join(''):'<section class="course-card"><h2>No lessons published yet</h2><p>Approved courses and lessons will appear here.</p></section>';notice(`${lessons.length} approved lesson${lessons.length===1?'':'s'} available.`)}catch(error){notice(error.message,true)}}
document.addEventListener('click',async event=>{const lang=event.target.closest('[data-language]');if(lang){const article=lang.closest('[data-lesson]'),body=article.querySelector('.lesson-body'),te=lang.dataset.language==='te';body.textContent=body.dataset[te?'te':'en'];article.querySelectorAll('[data-language]').forEach(button=>button.setAttribute('aria-pressed',String(button===lang)));return}const done=event.target.closest('[data-complete]');if(done){done.disabled=true;try{const article=done.closest('[data-lesson]'),was=done.textContent.startsWith('Mark as not');await api('/api/academy/progress/'+encodeURIComponent(done.dataset.complete),{method:'PUT',body:JSON.stringify({learnerId,completed:!was})});await load()}catch(error){notice(error.message,true);done.disabled=false}}});
load();
